import{_ as l,o,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const D=JSON.parse('{"title":"CDS G/H (Day 1) - RDMA Update","description":"","frontmatter":{"title":"CDS G/H (Day 1) - RDMA Update","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-24T00:00:00.000Z","tags":["RDMA更新","Ceph存储","Firefly升级","IO链式操作","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_RDMA_Update.md","filePath":"posts/2014/CDS_G_H_Day_1_-_RDMA_Update.md","lastUpdated":1780459816000}'),e={name:"posts/2014/CDS_G_H_Day_1_-_RDMA_Update.md"};function s(n,t,_,p,a,g){return o(),i("div",null,[...t[0]||(t[0]=[r("<p>会议纪要</p><p><strong>会议主题</strong>： RDMA更新及未来计划讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Matt, Benjamin, Seth, 以及其他相关研发人员</p><p><strong>会议内容</strong>：</p><p><strong>一、RDMA更新</strong></p><ol><li><strong>Firefly升级</strong>： Firefly升级正在进行中，目前进展顺利。</li><li><strong>Excelio消息接口更改</strong>： Excelio更新了内部消息接口，从固定数组16个元素减少到4个，并允许动态分配更大的数组，可能影响IO链式操作，需要进一步测试和优化。</li><li><strong>性能回归</strong>： Firefly升级后，发现存在性能回归问题，已采取措施解决，目前性能已恢复至Emperor水平，甚至有所提升。</li><li><strong>优化</strong>： 通过重新组织缓冲区和缓冲区列表，优化了与ATO2的交互，可能对性能有所贡献。</li><li><strong>单消息传递器</strong>： 讨论了使用单个编译或运行时选择的传递器，以提高效率和可维护性。</li><li><strong>通道支持</strong>： 讨论了在Excel传递器和传递器中添加通道支持，以实现不同消息流的优先级控制和更高效的连接管理。</li><li><strong>地址类型编码</strong>： 讨论了更改地址类型编码，以支持更高效的地址存储和混合协议访问。</li><li><strong>API迁移</strong>： 讨论了将用户从旧API迁移到新API，以简化代码并提高可维护性。</li></ol><p><strong>二、后续行动计划</strong></p><ol><li>Matt将测试新的IO缓冲区分配策略，并针对可能的问题进行优化。</li><li>Matt将继续进行性能测试，确保Firefly升级后的性能符合预期。</li><li>Matt将完成单消息传递器的实现，并开始实施Markdown功能。</li><li>Seth将完成Excelio分支的整理和测试，并准备合并到主分支。</li><li>团队将讨论并确定混合协议访问的需求和实现方案。</li></ol><p><strong>三、其他讨论</strong></p><ol><li>讨论了多协议访问的需求和实现方案，包括IPv4和IPv6的混合使用。</li><li>讨论了传递器创建函数的改进，以支持不同的传输类型。</li></ol><p><strong>四、会议总结</strong></p><p>本次会议对RDMA的更新和未来计划进行了全面讨论，明确了后续行动计划，并确定了下一步的工作重点。</p><p>改进点：</p><ul><li>保留了Ceph相关领域的英文原文关键词。</li><li>涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</li><li>对Excelio消息接口更改的影响进行了详细说明。</li><li>对后续行动计划进行了明确阐述。</li></ul>",15)])])}const c=l(e,[["render",s]]);export{D as __pageData,c as default};
